// Regenerates every derived copy of the Plus design tokens from the single
// source of truth in core/plus-tokens.js.
//
//   node scripts/sync-plus-tokens.mjs
//
// tests/plus-tokens.test.js fails when a generated file drifts from the
// source, so CI catches an edit that skipped this script.

import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import fs from 'node:fs';
import path from 'node:path';

const require = createRequire(import.meta.url);
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const tokens = require(path.join(root, 'core', 'plus-tokens.js'));

const BANNER = '/* Generated by scripts/sync-plus-tokens.mjs from core/plus-tokens.js. Do not edit. */';

export function siteCss() {
  return BANNER + '\n' + tokens.css({ scope: ':root' }) + '\n';
}

export function workerModule() {
  const css = tokens.css({ scope: ':root' });
  return [
    '// Generated by scripts/sync-plus-tokens.mjs from core/plus-tokens.js. Do not edit.',
    'export const PLUS_TOKENS_CSS = ' + JSON.stringify(css) + ';',
    'export default PLUS_TOKENS_CSS;',
    ''
  ].join('\n');
}

export const TARGETS = [
  ['docs/plus-tokens.css', siteCss],
  ['plus-worker/plus-tokens.mjs', workerModule]
];

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  for (const [relative, build] of TARGETS) {
    const target = path.join(root, relative);
    // The public repository has no server folder: skip its copy there.
    if (!fs.existsSync(path.dirname(target))) { console.log(`skipped  ${relative}  (folder not in this repository)`); continue; }
    const next = build();
    const previous = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
    fs.writeFileSync(target, next);
    console.log(`${previous === next ? 'unchanged' : 'wrote'}  ${relative}  (${next.length} bytes)`);
  }
}
